#include <bits/stdc++.h>
using namespace std;

int main() {
    // Precompute cumulative sums
    vector<long long> sums(51, 0);
    sums[0] = 1;
    for (int i = 1; i < 51; ++i) {
        sums[i] = sums[i - 1] + (1LL << i);
    }

    int h, n;
    cin >> h >> n;

    n += sums[h - 1];
    vector<long long> path;
    path.push_back(n);
    while (n != 1) {
        n /= 2;
        path.push_back(n);
    }
    reverse(path.begin(), path.end());

    long long answer = 0;
    long long node = 1;
    bool flip_flag = false;

    while (node != path[0]) {
        vector<long long> temp_path;
        long long temp_node = node;
        for (int i = 0; i < h; ++i) {
            temp_path.push_back(temp_node);
            if (!flip_flag) {
                temp_node *= 2;
            } else {
                temp_node = temp_node * 2 + 1;
            }
            flip_flag = !flip_flag;
        }
        if (temp_node == path[0]) {
            answer += h;
            break;
        }
        temp_path.push_back(temp_node);
        reverse(temp_path.begin(), temp_path.end());
        for (int i = 1; i <= h; ++i) {
            if (path[i] == temp_path[i]) {
                answer += sums[i - 1] + h - i + 1;
                h = i - 1;
                node = temp_path[i - 1];
                if (node == temp_path[i] * 2) {
                    node = temp_path[i] * 2 + 1;
                    flip_flag = false;
                } else {
                    node = temp_path[i] * 2;
                    flip_flag = true;
                }
                break;
            }
        }
    }
    cout << answer << "\n";
    return 0;
}
